+    if (tvb_memeql(tvb, offset, well_known_prefix, sizeof well_known_prefix) == 0) {
+        ipv4_addr = tvb_get_bits32(tvb, 96, 32, ENC_BIG_ENDIAN);
+        ipv4_prefix = 96;
+        ipv4_offset = 96;
+        ipv6_embed_ipv4 = true;
+    } else {
+        for (size_t j = 0; j < number_of_nat64_prefix; j++) {
